199: // ParseWorkspaceURI extracts and normalizes a file path from a workspace URI string.
200: // Supports file:///path, file:/path, percent-encoded characters (%20), and Windows drives (/C:/...).
201: func ParseWorkspaceURI(uriStr string) (string, error) {
202: 	uriStr = strings.TrimSpace(uriStr)
203: 	if uriStr == "" {
204: 		return "", fmt.Errorf("empty workspace URI")
205: 	}
206: 
207: 	raw := uriStr
208: 	if strings.HasPrefix(raw, "file://") {
209: 		raw = strings.TrimPrefix(raw, "file://")
210: 	} else if strings.HasPrefix(raw, "file:") {
211: 		raw = strings.TrimPrefix(raw, "file:")
212: 	}
213: 
214: 	unescaped, err := url.PathUnescape(raw)
215: 	if err != nil {
