361: // DeduplicateSummaries merges conversation summaries from the app and CLI stores into a single map.
362: // For conversations present in both stores:
363: // - It marks InAppStore=true and InCLIStore=true, setting SourceStore="both".
364: // - If the CLI record is more recent, its timestamp, idle, and killed state are updated.
365: // - It retains the higher step count.
366: // - It preserves non-empty workspace paths and parent conversation IDs from either store.
367: func DeduplicateSummaries(appSummaries, cliSummaries map[string]*ConversationSummary) map[string]*ConversationSummary {
368: 	merged := make(map[string]*ConversationSummary, len(appSummaries)+len(cliSummaries))
369: 
370: 	for id, s := range appSummaries {
371: 		copySummary := *s
372: 		copySummary.InAppStore = true
373: 		copySummary.SourceStore = "app"
374: 		merged[id] = &copySummary
375: 	}
376: 
377: 	for id, cliSummary := range cliSummaries {
378: 		existing, ok := merged[id]
379: 		if !ok {
380: 			copySummary := *cliSummary
381: 			copySummary.InCLIStore = true
382: 			copySummary.SourceStore = "cli"
383: 			merged[id] = &copySummary
384: 			continue
385: 		}
386: 
387: 		// Present in both stores: de-duplicate!
388: 		existing.InCLIStore = true
389: 		existing.SourceStore = "both"
390: 
391: 		// Merge workspace paths if app was missing them
392: 		if len(existing.WorkspacePaths) == 0 && len(cliSummary.WorkspacePaths) > 0 {
393: 			existing.WorkspacePaths = cliSummary.WorkspacePaths
394: 			existing.WorkspaceURIs = cliSummary.WorkspaceURIs
395: 		}
396: 
397: 		// Retain parent conversation ID if one had it
398: 		if existing.ParentConversationID == "" && cliSummary.ParentConversationID != "" {
399: 			existing.ParentConversationID = cliSummary.ParentConversationID
400: 		}
401: 
402: 		// Keep highest step count
403: 		if cliSummary.StepCount > existing.StepCount {
404: 			existing.StepCount = cliSummary.StepCount
405: 		}
406: 
407: 		// If CLI is more recently modified, update timestamp and status
408: 		if cliSummary.LastModifiedTime.After(existing.LastModifiedTime) {
409: 			existing.LastModifiedTime = cliSummary.LastModifiedTime
410: 			existing.NotFullyIdle = cliSummary.NotFullyIdle
411: 			existing.Killed = cliSummary.Killed
412: 			if cliSummary.Title != "" {
413: 				existing.Title = cliSummary.Title
414: 			}
415: 			if cliSummary.Preview != "" {
416: 				existing.Preview = cliSummary.Preview
417: 			}
418: 		}
419: 	}
420: 
421: 	return merged
422: }
