424: // LinkSubagents populates the SubagentIDs slice of each parent conversation based on parent_conversation_id.
425: func LinkSubagents(summaries map[string]*ConversationSummary) {
426: 	for _, conv := range summaries {
427: 		if conv.ParentConversationID == "" || conv.ParentConversationID == conv.ConversationID {
428: 			continue
429: 		}
430: 		if parent, ok := summaries[conv.ParentConversationID]; ok {
431: 			alreadyAdded := false
432: 			for _, childID := range parent.SubagentIDs {
433: 				if childID == conv.ConversationID {
434: 					alreadyAdded = true
