445: // AttributeConversations maps conversation summaries to enrolled repositories.
446: // Conversations are mapped if any workspace path matches an enrolled repo.
447: // Subagents with no direct matching workspace inherit the repository attribution of their parent.
448: func AttributeConversations(
449: 	summaries map[string]*ConversationSummary,
450: 	enrolledRepos map[string]config.RegistryEntry,
451: ) map[string]*AttributedConversation {
452: 	attributed := make(map[string]*AttributedConversation)
453: 
454: 	// Helper to check if a workspace path matches an enrolled repo
455: 	matchRepo := func(wsPath string) *config.RegistryEntry {
456: 		cleanWs := filepath.Clean(wsPath)
457: 		evalWs, _ := filepath.EvalSymlinks(cleanWs)
458: 
459: 		for root, entry := range enrolledRepos {
460: 			cleanRoot := filepath.Clean(root)
461: 			evalRoot, _ := filepath.EvalSymlinks(cleanRoot)
462: 
463: 			if cleanWs == cleanRoot || (evalWs != "" && evalWs == cleanRoot) ||
464: 				(evalRoot != "" && cleanWs == evalRoot) || (evalWs != "" && evalWs == evalRoot) {
465: 				return &entry
466: 			}
467: 
468: 			if config.IsSubdir(cleanWs, cleanRoot) || config.IsSubdir(cleanRoot, cleanWs) {
469: 				return &entry
470: 			}
471: 			if evalWs != "" && config.IsSubdir(evalWs, cleanRoot) {
472: 				return &entry
473: 			}
474: 		}
475: 		return nil
476: 	}
477: 
478: 	// 1. Direct attribution via workspace_paths
479: 	for id, summary := range summaries {
480: 		for _, wsPath := range summary.WorkspacePaths {
481: 			if entry := matchRepo(wsPath); entry != nil {
